class CircularQueue:
    def __init__(self, k):
        self.size = k
        self.arr = [0] * k
        self.front = -1
        self.rear = -1

    def is_full(self):
        return (self.rear + 1) % self.size == self.front

    def is_empty(self):
        return self.front == -1

    def function1(self, value):
        if self.is_full():
            return False
        if self.is_empty():
            self.front = 0
        self.rear = (self.rear + 1) % self.size
        self.arr[self.rear] = value
        return True
```

